 return `<section class="card host-toolbar"><div class="eyebrow">VÄRDKONTROLLER</div><div class="host-actions"><button id="hostPause" class="secondary">${room?.paused?'Fortsätt':'Pausa'}</button><button id="hostSkip" class="secondary">Hoppa över fråga</button><button id="hostRestart" class="secondary">Starta om fråga</button><button id="hostScores" class="secondary">Justera poäng</button><button id="hostEnd" class="secondary">Avsluta spel</button></div><div id="scoreAdmin" class="hidden score-admin">${(room?.players||[]).map(p=>`<div class="player-live"><span>${esc(p.avatar)} ${esc(p.name)}</span><span><button data-minus="${esc(p.sessionId)}" class="tiny-btn">−100</button><button data-plus="${esc(p.sessionId)}" class="tiny-btn">+100</button><button data-kick="${esc(p.sessionId)}" class="tiny-btn danger-mini" ${p.sessionId===me.sessionId?'disabled':''}>Ta bort</button></span></div>`).join('')}</div></section>`
