 if(sortMode){const board=document.getElementById('sortBoard'),move=(el,dir)=>{const sib=dir<0?el.previousElementSibling:el.nextElementSibling;if(sib)board.insertBefore(dir<0?el:sib,dir<0?sib:el)};board.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>move(b.closest('.sort-item'),-1));board.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>move(b.closest('.sort-item'),1));let drag=null;board.querySelectorAll('.sort-item').forEach(el=>{el.ondragstart=()=>drag=el;el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(drag&&drag!==el)board.insertBefore(drag,el)}});document.getElementById('sortSubmit').onclick=()=>submit(-1,stake,'','',0,[...board.querySelectorAll('.sort-item b')].map(x=>x.textContent))}
