function submit(i,stake=100,textAnswer='',numericAnswer='',cluesUsed=0,order=[],mapLat=null,mapLon=null,pinX=null,pinY=null){if(answered||!socket?.connected)return;answered=true;document.querySelectorAll('[data-i]').forEach((b,j)=>{b.disabled=true;if(j===i)b.classList.add('selected')});socket.emit('submitAnswer',{code:room.code,sessionId:me.sessionId,questionId:question.id,answerIndex:i,stake,textAnswer,numericAnswer,cluesUsed,order,mapLat,mapLon,pinX,pinY},r=>{const e=document.getElementById('answerProgress');if(e)e.textContent=r?.ok?(r.responseMs?`✓ SVAR LÅST · ${(r.responseMs/1000).toFixed(1)} s`:'✓ SVAR LÅST'):(r?.error||'Kunde inte skicka')})}
function updateMiniScore(){const e=document.getElementById('miniScore');if(e)e.innerHTML=scoreHtml()}
function mapRevealHtml(r){const pts=(r.results||[]).filter(x=>Number.isFinite(x.mapLat)&&Number.isFinite(x.mapLon));if(!pts.length)return '';const pins=pts.map(x=>{const p=room.players.find(z=>z.sessionId===x.sessionId),left=((x.mapLon+180)/360*100),top=((90-x.mapLat)/180*100);return `<span class="result-map-pin" style="left:${left}%;top:${top}%" title="${esc(p?.name||'Spelare')} · ${x.distanceKm??'?'} km">${esc(p?.avatar||'📍')}</span>`}).join('');const target=r.specialData?`<span class="result-map-target" style="left:${((r.specialData.lon+180)/360*100)}%;top:${((90-r.specialData.lat)/180*100)}%">★</span>`:'';return `<div class="result-map" style="background-image:url('world-map.svg')">${pins}${target}</div><div class="map-ranking">${pts.slice().sort((a,b)=>(a.distanceKm??1e9)-(b.distanceKm??1e9)).map((x,i)=>{const p=room.players.find(z=>z.sessionId===x.sessionId);return `<span>${i+1}. ${esc(p?.name||'')} · ${x.distanceKm} km</span>`}).join('')}</div>`}
function renderResult(r){clearInterval(currentTimer);const mine=r.results.find(x=>x.sessionId===me.sessionId);if(mine?.correct)beep(760,.12);else beep(220,.12);A.innerHTML=`<section class="card"><div class="${mine?.correct?'feedback good':'feedback bad'}"><b>${r.skipped?'Frågan hoppades över':mine?.correct?'Rätt!':'Inte rätt'}</b>${mine?.gain?` · ${mine.gain>0?'+':''}${mine.gain} poäng`:''}${mine?.predictionBonus?' · 🔮 +50 prediction':''}</div>${r.secretBonus?'<div class="secret-bonus">✨ HEMLIG BONUSFRÅGA ×3!</div>':''}<div class="correct-answer"><b>Rätt svar:</b> ${esc(r.correctAnswer)}<br><span class="muted">${esc(r.explanation)}</span>${mine?.distanceKm!=null?`<br><strong>Din markering: ${mine.distanceKm} km från målet</strong>`:''}${mine?.pinDistance!=null?`<br><strong>Din precision: ${Math.max(0,Math.round((1-mine.pinDistance)*100))}%</strong>`:''}</div>${r.type==='map'?mapRevealHtml(r):''}${r.ratingPrompt?`<div class="question-rating"><span>Var detta en bra fråga?</span><button data-rate="up">👍</button><button data-rate="down">👎</button></div>`:''}</section><section class="card"><div class="eyebrow">${room?.settings?.soloMode?'DIN POÄNG':'STÄLLNING'}</div>${scoreHtml()}${isHost()?`<button id="next" class="primary xl">${room.settings?.director?'Nästa nu · annars automatiskt':'Nästa'}</button>${room.settings?.director?'<p class="statusline">🎬 Director fortsätter automatiskt om några sekunder.</p>':''}`:'<p class="statusline">Väntar på nästa fråga…</p>'}</section>${room?.settings?.soloMode?'':reactionBar()}${hostToolbar()}`;document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=async()=>{await fetch('/api/question-rating',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({questionId:r.questionId,vote:b.dataset.rate})});b.parentElement.innerHTML='<span>✓ Tack!</span>'});bindReactions();if(isHost())document.getElementById('next').onclick=()=>socket.emit('nextQuestion',{code:room.code,hostToken:me.hostToken},x=>{if(!x?.ok)alert(x?.error||'Kunde inte fortsätta.')});bindHostToolbar()}
function renderRoundBreak(r){room=r.room||room;A.innerHTML=`<section class="card winner"><div class="trophy">📊</div><div class="eyebrow">RUNDPAUS</div><h2>Runda ${Math.max(1,(room.round||1)-1)} klar</h2><p>Nästa runda: ${room.round}/${room.rounds}</p></section><section class="card"><div class="eyebrow">${room?.settings?.soloMode?'DIN POÄNG':'STÄLLNING'}</div>${scoreHtml()}</section>${isHost()?'<section class="card"><button id="continueRound" class="primary xl">Starta nästa runda</button></section>':'<section class="card"><p class="statusline">Väntar på värden…</p></section>'}`;if(isHost())document.getElementById('continueRound').onclick=()=>socket.emit('continueRound',{code:room.code,hostToken:me.hostToken})}
function showDrama(d){let e=document.getElementById('dramaOverlay');if(e)e.remove();e=document.createElement('div');e.id='dramaOverlay';e.className='drama-overlay';e.innerHTML=`<div><span>${esc(d.icon||'✨')}</span><b>${esc(d.title||'')}</b><small>${esc(d.text||'')}</small></div>`;document.body.appendChild(e);beep(620,.16);setTimeout(()=>e.classList.add('show'),20);setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),300)},3000)}
function renderFinal(r){
 const teams=(room.teams||[]),players=room.players.slice().sort((a,b)=>b.score-a.score),winner=room.mode==='teams'?teams[0]:players[0],ins=r.insights||{};
 beep(880,.3);
 A.innerHTML=`<section class="card winner"><div class="trophy">🏆</div><div class="eyebrow">${room?.settings?.soloMode?'SOLORESULTAT':r.tie?'OAVGJORT':'VINNARE'}</div><h2>${room?.settings?.soloMode?'Bra spelat!':r.tie?'Tie-break krävs':room.mode==='teams'?esc(winner?.name||'Vinnarlaget'):esc((winner?.avatar||'')+' '+(winner?.name||'Vinnaren'))}</h2><p>${winner?.score||0} poäng</p></section><section class="card"><div class="eyebrow">${room?.settings?.soloMode?'DITT RESULTAT':'SLUTSTÄLLNING'}</div>${scoreHtml()}</section><section class="card"><div class="eyebrow">KVÄLLENS STATISTIK</div><div class="feature-grid">${ins.hardest?`<div><b>Svåraste frågan</b><small>${esc(ins.hardest.text)} · ${ins.hardest.accuracy}% rätt</small></div>`:''}${ins.fastest?`<div><b>Snabbast</b><small>${esc(ins.fastest.avatar)} ${esc(ins.fastest.name)} · ${(ins.fastest.avgResponseMs/1000).toFixed(1)} s</small></div>`:''}${ins.bestStreak?`<div><b>Bästa streak</b><small>${esc(ins.bestStreak.avatar)} ${esc(ins.bestStreak.name)} · ${ins.bestStreak.value} rätt i rad</small></div>`:''}${ins.imageMaster?`<div><b>Bildmästare</b><small>${esc(ins.imageMaster.avatar)} ${esc(ins.imageMaster.name)} · ${ins.imageMaster.correct}/${ins.imageMaster.total}</small></div>`:''}${ins.categoryExpert?`<div><b>Kategoriexpert</b><small>${esc(ins.categoryExpert.avatar)} ${esc(ins.categoryExpert.name)} · ${esc(ins.categoryExpert.category)} ${ins.categoryExpert.correct}/${ins.categoryExpert.total}</small></div>`:''}${ins.comeback?`<div><b>Bästa comeback</b><small>${esc(ins.comeback.avatar)} ${esc(ins.comeback.name)} · ${ins.comeback.from}:a till ${ins.comeback.to}:a</small></div>`:''}</div></section>${isHost()?`<section class="card">${r.tie?'<button id="tiebreak" class="primary xl">Starta tie-break</button>':''}<button id="again" class="primary">▶ Spela igen direkt</button></section>`:''}<section class="card"><div class="eyebrow">DINA ACHIEVEMENTS</div><div class="achievement-grid">${(r.achievements?.[me.sessionId]||[]).map(a=>`<div class="achievement"><span>${esc(a.icon)}</span><b>${esc(a.name)}</b><small>${esc(a.text)}</small></div>`).join('')||'<p class="muted">Nya achievements väntar nästa gång.</p>'}</div></section><section class="card"><button id="shareFinal" class="secondary">📸 Dela resultatkort</button><button id="profileBackup" class="secondary">💾 Exportera min profil</button><button id="hallFinal" class="secondary">Hall of Fame</button><a class="secondary" href="history.html">Spelkvällar & liga</a><button id="exit" class="secondary">Till startsidan</button></section>`;
 if(isHost()&&r.tie)document.getElementById('tiebreak').onclick=()=>socket.emit('startTiebreaker',{code:room.code,hostToken:me.hostToken});
 if(isHost())document.getElementById('again').onclick=()=>socket.emit('replaySame',{code:room.code,hostToken:me.hostToken},x=>{if(!x?.ok)showToast(x?.error||'Kunde inte starta om.')});
 document.getElementById('hallFinal')?.addEventListener('click',showHall);document.getElementById('exit').onclick=()=>{clearRoom();location.href='index.html'}
}
init();
